msg.allEntries = msg.payload;
msg.processedEntries = [];
msg.currentIndex = 0;

return msg;

const entry = msg.allEntries[msg.currentIndex];

if (entry.files && entry.files.length > 0) {
    msg.currentEntry = entry;
    msg.filesToFetch = entry.files;
    msg.fetchedFiles = [];
    msg.currentFileIndex = 0;
    msg.hasFiles = true;
} else {
    entry.wasosFiles = [];
    msg.processedEntries.push(entry);
    msg.currentIndex++;
    msg.hasFiles = false;
}

return msg;

const rayvn_config = global.get('rayvn_config');
const rayvn_url = global.get('rayvn_url');
const fileInfo = msg.filesToFetch[msg.currentFileIndex];

if (!fileInfo || !fileInfo.id) {
    node.warn('Fil mangler ID: ' + JSON.stringify(fileInfo));
    msg.currentFileIndex++;
    if (msg.currentFileIndex >= msg.filesToFetch.length) {
        return [null, msg];
    }
    return [msg, null];
}

// Lagre fil-metadata
msg.currentFile = {
    id: fileInfo.id,
    filename: fileInfo.name || 'unknown',
    extension: fileInfo.name ? fileInfo.name.split('.').pop().toLowerCase() : 'bin',
    size: fileInfo.size,
    originalUrl: fileInfo.url
};

const ext = msg.currentFile.extension;
const mimeTypes = {
    'png': 'image/png',
    'jpg': 'image/jpeg',
    'jpeg': 'image/jpeg',
    'gif': 'image/gif',
    'webp': 'image/webp',
    'pdf': 'application/pdf'
};
msg.currentFile.filetype = mimeTypes[ext] || 'application/octet-stream';

// Bygg request til /files/{fileId}
msg.url = rayvn_url + '/files/' + fileInfo.id;
msg.headers = {
    "Authorization": "Bearer " + rayvn_config.api_key
};

node.log('Henter fil-info: ' + msg.url);

return [msg, null];

const response = msg.payload;

node.log('File info response status: ' + msg.statusCode);
node.log('File info response: ' + JSON.stringify(response).substring(0, 500));

if (msg.statusCode !== 200) {
    node.warn('Kunne ikke hente fil-info. Status: ' + msg.statusCode);
    // Prøv med original URL som fallback
    msg.signedUrl = msg.currentFile.originalUrl;
} else if (response && response.url) {
    // Bruk URL fra response
    msg.signedUrl = response.url;
    node.log('Fikk URL fra /files endpoint: ' + msg.signedUrl);
} else {
    // Fallback til original URL
    node.warn('Ingen URL i response, bruker original: ' + msg.currentFile.originalUrl);
    msg.signedUrl = msg.currentFile.originalUrl;
}

return msg;

const rayvn_config = global.get('rayvn_config');

msg.url = msg.signedUrl;

// Prøv med Bearer token først
msg.headers = {
    "Authorization": "Bearer " + rayvn_config.api_key
};

node.log('Henter bilde fra: ' + msg.url);

return msg;

const buffer = msg.payload;

node.log('Image fetch status: ' + msg.statusCode + ', size: ' + (buffer ? buffer.length : 0));

if (buffer && buffer.length > 0 && msg.statusCode === 200) {
    const blob = Array.from(new Uint8Array(buffer));

    const wasosFile = {
        filename: msg.currentFile.filename,
        extension: msg.currentFile.extension,
        filetype: msg.currentFile.filetype,
        blob: blob
    };

    msg.fetchedFiles.push(wasosFile);
    node.log('SUCCESS: Hentet bilde: ' + msg.currentFile.filename + ' (' + blob.length + ' bytes)');
} else {
    node.warn('FAILED: Kunne ikke hente bilde. Status: ' + msg.statusCode + ', URL: ' + msg.url);
}

// Neste fil
msg.currentFileIndex++;

if (msg.currentFileIndex < msg.filesToFetch.length) {
    return [msg, null];
} else {
    return [null, msg];
}

const entry = msg.currentEntry;
entry.wasosFiles = msg.fetchedFiles || [];
msg.processedEntries.push(entry);

msg.currentIndex++;

// Rydd opp
delete msg.currentEntry;
delete msg.filesToFetch;
delete msg.fetchedFiles;
delete msg.currentFileIndex;
delete msg.currentFile;
delete msg.hasFiles;
delete msg.url;
delete msg.headers;
delete msg.statusCode;
delete msg.signedUrl;

return msg;

if (msg.currentIndex < msg.allEntries.length) {
    return [msg, null];
} else {
    msg.payload = msg.processedEntries;

    delete msg.allEntries;
    delete msg.processedEntries;
    delete msg.currentIndex;

    node.log('Ferdig! Prosessert ' + msg.payload.length + ' entries');

    return [null, msg];
}
